\title{A Shift-Invariant Row-Sum Law for the Extended Eulerian Numbers}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
The classical Eulerian numbers $\eul{n}{k}$ count permutations of
$\{1,\dots,n\}$ by their number of descents and satisfy the row identity
$\sum_k \eul{n}{k} = n!$. We study a one-parameter deformation, the
\emph{extended Eulerian numbers} $A(n,k,s)$, obtained by inserting a continuous
real shift $s$ into the classical alternating-binomial closed form; at $s=0$ they
reduce to the ordinary Eulerian numbers. We prove two results with a single
self-contained technique, the forward finite-difference calculus. First, a
\emph{boundary vanishing theorem}: $A(n,k,s)=0$ for all $k\ge n+1$ and all real
$s$, so every deformed row is supported on $k=0,\dots,n$. Second, a
\emph{shift-invariant row-sum law}: for every $n$ and every real $s$,
$\sum_{k=0}^{n} A(n,k,s) = n!$, independent of the shift. The row sum is thus a
rigid invariant of the deformation, and the classical identity is recovered at
$s=0$. The proofs never invoke the Eulerian recurrence; they rest only on the
closed form and three structural facts about iterated forward differences.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The Eulerian numbers}
Let $n\in\N$ and let $\sigma$ be a permutation of $\{1,\dots,n\}$. A
\emph{descent} of $\sigma$ is an index $j$ with $\sigma(j)>\sigma(j+1)$. The
\emph{Eulerian number} $\eul{n}{k}$ is the number of permutations of
$\{1,\dots,n\}$ with exactly $k$ descents. These numbers form a symmetric
triangular array. Two elementary facts organize them: the symmetry
$\eul{n}{k}=\eul{n}{n-1-k}$ (reverse a permutation) and the row sum
\begin{equation}
\sum_{k=0}^{n-1}\eul{n}{k}=n!,
\end{equation}
which holds because grouping the $n!$ permutations by descent count partitions
them. A classical closed form expresses the Eulerian numbers as an alternating
binomial sum of powers:
\begin{equation}\label{eq:classical}
\eul{n}{k}=\sum_{i=0}^{k}(-1)^i\binom{n+1}{i}(k+1-i)^n.
\end{equation}

\subsection{A continuous deformation}

\begin{definition}[Extended Eulerian numbers]
For $n,k\in\N$ and $s\in\R$, define
\[
A(n,k,s)=\sum_{i=0}^{k}(-1)^i\binom{n+1}{i}\bigl((k+1-i)-s\bigr)^{n}\in\R.
\]
\end{definition}

At $s=0$ we have $A(n,k,0)=\eul{n}{k}$ by \eqref{eq:classical}. For generic $s$,
$A(n,k,s)$ is a real number that need not be an integer, need not be nonnegative,
and does not inherit the symmetry of the classical row. The shift $s$ is a
continuous dial deforming the entire triangle.

\subsection{Results}
\begin{theorem}[Boundary vanishing]\label{thm:A}
For all $n,k$ with $k\ge n+1$ and all $s\in\R$, $A(n,k,s)=0$. Hence the $n$-th
deformed row is supported on $k\in\{0,1,\dots,n\}$.
\end{theorem}

\begin{theorem}[Shift-invariant row sum]\label{thm:B}
For all $n\in\N$ and all $s\in\R$,
\[
\sum_{k=0}^{n}A(n,k,s)=n!.
\]
In particular the row sum is independent of $s$, and $s=0$ recovers
$\sum_k \eul{n}{k}=n!$.
\end{theorem}

The novelty is not the classical identity but its rigidity: the individual entries
vary continuously and nontrivially with $s$, yet the row total is frozen. Both
proofs are conducted entirely within the forward finite-difference calculus and
never use the Eulerian recurrence. This gives a non-circular account, since the
numbers are \emph{defined} by the closed form rather than by the recurrence.

\section{The finite-difference toolkit}

\begin{definition}
For a function $f$ on $\R$ (or on $\N$) the \emph{forward difference with step
$1$} is $(\Delta f)(x)=f(x+1)-f(x)$, with $n$-fold iterate $\Delta^n$ and
$\Delta^0=\mathrm{id}$.
\end{definition}

\begin{lemma}[Explicit expansion]\label{lem:expand}
For every $f$, every $n\in\N$, and every $x$,
\[
(\Delta^n f)(x)=\sum_{k=0}^{n}(-1)^{\,n-k}\binom{n}{k}f(x+k).
\]
\end{lemma}
\begin{proof}
Induction on $n$ using $\binom{n+1}{k}=\binom{n}{k}+\binom{n}{k-1}$; the base case
$n=0$ is trivial and the inductive step regroups the telescoped shifts.
\end{proof}

\begin{lemma}[Degree annihilation]\label{lem:degree}
If $p$ is a real polynomial of degree at most $n$, then $\Delta^{n+1}p\equiv0$.
\end{lemma}
\begin{proof}
Each application of $\Delta$ lowers the degree by exactly one, so after $n+1$
applications a polynomial of degree $\le n$ becomes the zero polynomial.
\end{proof}

\begin{lemma}[Factorial value, with translation invariance]\label{lem:factorial}
For every $n\in\N$ and every constant $c\in\R$,
\[
\Delta^n\!\bigl[x\mapsto(x+c)^n\bigr]\equiv n!.
\]
In particular $\Delta^n[x\mapsto x^n]\equiv n!$.
\end{lemma}
\begin{proof}
Since $\Delta$ commutes with translation of the argument,
$\Delta^n[g(\,\cdot\,+c)]=(\Delta^n g)(\,\cdot\,+c)$ for $g(x)=x^n$, so it suffices
to prove $\Delta^n[x^n]=n!$. By Lemma~\ref{lem:degree} the result is a constant;
by Lemma~\ref{lem:expand} it equals $\sum_{k=0}^n(-1)^{n-k}\binom{n}{k}k^n=n!$
(the standard alternating sum evaluating the $n$-th difference of $x^n$).
\end{proof}

The closed form defining $A(n,k,s)$ is an alternating binomial sum, and
Lemma~\ref{lem:expand} says that iterated differences are exactly alternating
binomial sums. The two coincide once the summation index is reflected; this
identification drives both theorems.

\section{Boundary vanishing}

\begin{proof}[Proof of Theorem~\ref{thm:A}]
Fix $k\ge n+1$. In $A(n,k,s)=\sum_{i=0}^{k}(-1)^i\binom{n+1}{i}(k+1-i-s)^n$ the
coefficient $\binom{n+1}{i}$ vanishes for $i>n+1$, so
\begin{equation}\label{eq:trunc}
A(n,k,s)=\sum_{i=0}^{n+1}(-1)^i\binom{n+1}{i}(k+1-i-s)^n.
\end{equation}
Reflect the index by $i\mapsto n+1-i$, using
$\binom{n+1}{n+1-i}=\binom{n+1}{i}$. Then the right-hand side of \eqref{eq:trunc}
equals the alternating binomial sum
\[
\sum_{i=0}^{n+1}(-1)^{(n+1)-i}\binom{n+1}{i}\,p\bigl((k-n)+i\bigr),
\qquad p(x):=(x-s)^n,
\]
which by Lemma~\ref{lem:expand} is $(\Delta^{n+1}p)(k-n)$. Since $p$ has degree
$n$, Lemma~\ref{lem:degree} gives $\Delta^{n+1}p\equiv0$, so $A(n,k,s)=0$.
\end{proof}

\begin{remark}
The vanishing is a degree phenomenon, uniform in the shift: nothing is used about
$k$ beyond $k\ge n+1$, and nothing about $s$ beyond $\deg\,(x-s)^n=n$.
\end{remark}

\section{The shift-invariant row sum}

\begin{definition}
For $n\in\N$ and $s\in\R$ set
\[
Q(t)=\sum_{m=0}^{t-1}(m+1-s)^n,\qquad t\in\N,\quad Q(0)=0.
\]
\end{definition}

\begin{lemma}\label{lem:dQ}
$(\Delta Q)(t)=(t+1-s)^n$ for all $t\in\N$.
\end{lemma}
\begin{proof}
$(\Delta Q)(t)=Q(t+1)-Q(t)=(t+1-s)^n$ by telescoping.
\end{proof}

\begin{lemma}[Fubini reindexing]\label{lem:fubini}
For every $n$ and $s$,
\[
\sum_{k=0}^{n}A(n,k,s)=\sum_{i=0}^{n}(-1)^i\binom{n+1}{i}Q(n+1-i).
\]
\end{lemma}
\begin{proof}
Interchanging the order of summation over the triangle
$\{(k,i):0\le i\le k\le n\}$,
\[
\sum_{k=0}^{n}A(n,k,s)
=\sum_{i=0}^{n}(-1)^i\binom{n+1}{i}\sum_{k=i}^{n}(k+1-i-s)^n.
\]
In the inner sum put $m=k-i$; then $m$ ranges over $0,\dots,n-i$ and
$k+1-i-s=m+1-s$, so the inner sum is $Q(n+1-i)$.
\end{proof}

\begin{lemma}\label{lem:rowdiff}
$\displaystyle\sum_{k=0}^{n}A(n,k,s)=(\Delta^{n+1}Q)(0)$.
\end{lemma}
\begin{proof}
From Lemma~\ref{lem:fubini}, reindex by $j=n+1-i$, using
$(-1)^i=(-1)^{n+1-j}$ and $\binom{n+1}{i}=\binom{n+1}{j}$:
\[
\sum_{i=0}^{n}(-1)^i\binom{n+1}{i}Q(n+1-i)
=\sum_{j=1}^{n+1}(-1)^{(n+1)-j}\binom{n+1}{j}Q(j).
\]
The $j=0$ term is $(-1)^{n+1}Q(0)=0$, so the sum may be extended to
$j=0,\dots,n+1$; by Lemma~\ref{lem:expand} (with $f=Q$ at $x=0$) it equals
$(\Delta^{n+1}Q)(0)$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:B}]
By Lemma~\ref{lem:rowdiff} the row sum is $(\Delta^{n+1}Q)(0)$. Peeling off one
difference and using Lemma~\ref{lem:dQ},
\[
\Delta^{n+1}Q=\Delta^{n}(\Delta Q)=\Delta^{n}\bigl[t\mapsto(t+1-s)^n\bigr].
\]
The inner function is $t\mapsto(t+(1-s))^n$, a shifted monomial of degree $n$, so
by Lemma~\ref{lem:factorial} with $c=1-s$ it equals the constant $n!$. Evaluating
at $0$ gives $(\Delta^{n+1}Q)(0)=n!$, hence $\sum_{k=0}^{n}A(n,k,s)=n!$.
\end{proof}

\begin{remark}
The parameter $s$ enters only as the translation constant $c=1-s$ inside the
monomial, and $\Delta^n$ of a degree-$n$ polynomial depends only on the leading
coefficient, which translation does not change. The row sum is therefore blind to
$s$.
\end{remark}

\section{Applications and context}

\subsection{Finite calculus}
The Eulerian numbers are the change-of-basis coefficients between ordinary powers
and falling-factorial bases (Worpitzky's identity
$x^n=\sum_k\eul{n}{k}\binom{x+k}{n}$). The extended numbers $A(n,k,s)$ are the
coefficients for the shifted power $(x-s)^n$, and Theorem~\ref{thm:B} states that
the total mass of the decomposition is conserved under the shift, a discrete
analogue of translation invariance of an integral.

\subsection{Sums of uniform random variables}
For independent $U_1,\dots,U_n$ uniform on $[0,1]$, the density of
$S_n=U_1+\cdots+U_n$ (the Irwin--Hall distribution) is a piecewise polynomial
governed by the Eulerian numbers. The shift corresponds to sliding the sum
$S_n-s$, and conservation of total probability is, after normalization by $n!$,
the row-sum invariant of Theorem~\ref{thm:B}.

\subsection{Non-circular foundations}
By taking the closed form as the definition and proving the row sum purely from
the difference calculus, we avoid the usual loop (define by recurrence, prove the
closed form, recover the recurrence). The development needs only
Lemmas~\ref{lem:expand}--\ref{lem:factorial}.

\section{Future directions}
(1) Higher-step and multivariate shifts, where the factorial value becomes
$h^n n!$. (2) $q$-deformations built from $q$-binomial coefficients. (3) Signed and
colored descents (types $B$ and beyond). (4) Which symmetric functions of a
deformed row, beyond the first moment, are invariant under $s$.

\section{Conclusion}
We introduced the extended Eulerian numbers $A(n,k,s)$ and established two
uniform-in-$s$ results by a single finite-difference argument: the deformed
triangle stays triangular, and every deformed row sums to $n!$. The classical
identity emerges as the snapshot at $s=0$ of a rigid law, and the proofs rest only
on the annihilation, factorial, and expansion properties of the forward difference
operator.

\end{document}

