"""Extended Eulerian row calculator (exact rational arithmetic)."""
from fractions import Fraction
from math import comb, factorial
from typing import List

def extended_eulerian(n: int, k: int, s: Fraction) -> Fraction:
    return sum(Fraction((-1) ** i) * comb(n + 1, i) * (Fraction(k + 1 - i) - s) ** n
               for i in range(k + 1))

def row(n: int, s: Fraction) -> List[Fraction]:
    return [extended_eulerian(n, k, s) for k in range(n + 1)]

for s in [Fraction(0), Fraction(1, 2), Fraction(-1), Fraction(3, 4)]:
    r = row(4, s)
    print(f"s={s}: row={[str(x) for x in r]}  sum={sum(r)}  (4! = {factorial(4)})")

"""Verify boundary vanishing A(n,k,s)=0 for k>=n+1 across many shifts."""
from fractions import Fraction
from math import comb

def A(n: int, k: int, s: Fraction) -> Fraction:
    return sum(Fraction((-1) ** i) * comb(n + 1, i) * (Fraction(k + 1 - i) - s) ** n
               for i in range(k + 1))

shifts = [Fraction(-2), Fraction(0), Fraction(1, 3), Fraction(9, 5)]
for n in range(1, 6):
    for s in shifts:
        assert all(A(n, k, s) == 0 for k in range(n + 1, n + 6)), (n, s)
print("Boundary vanishing confirmed for n=1..5 and all tested shifts.")

"""Confirm row sum = (Delta^{n+1} Q)(0) = n! (the proof mechanism)."""
from fractions import Fraction
from math import comb, factorial
from typing import List, Sequence

def A(n: int, k: int, s: Fraction) -> Fraction:
    return sum(Fraction((-1) ** i) * comb(n + 1, i) * (Fraction(k + 1 - i) - s) ** n
               for i in range(k + 1))

def diff(seq: Sequence[Fraction], times: int) -> List[Fraction]:
    out = list(seq)
    for _ in range(times):
        out = [out[j + 1] - out[j] for j in range(len(out) - 1)]
    return out

def Q(n: int, s: Fraction, t: int) -> Fraction:
    return sum((Fraction(m + 1) - s) ** n for m in range(t))

for n in range(2, 7):
    for s in [Fraction(0), Fraction(3, 4), Fraction(-2)]:
        table = [Q(n, s, t) for t in range(n + 2)]
        top = diff(table, n + 1)[0]
        rowsum = sum(A(n, k, s) for k in range(n + 1))
        assert top == rowsum == factorial(n)
print("Verified: row sum = (Delta^(n+1) Q)(0) = n! for n=2..6.")

